#!/bin/bash
# GENERATED by scripts/make_task.py from specs/fix-slugify-accents/spec.toml. Do not edit.
# Verifier: hidden FAIL_TO_PASS tests + PASS_TO_PASS tests.
# No "set -e": the reward file must always be written.

REWARD_DIR=/logs/verifier
mkdir -p "$REWARD_DIR"

f2p=0
p2p=0

if cd /app; then
    # Reset every file the test patch touches (the agent may have edited or
    # created them), then apply the hidden tests.
    git checkout -q HEAD -- tests/test_accents.py 2>/dev/null || rm -f tests/test_accents.py
    if git apply /tests/tests.patch; then
        echo "=== FAIL_TO_PASS (hidden tests) ==="
        if python -m pytest -rA -p no:cacheprovider tests/test_accents.py; then
            f2p=1
        fi

        echo "=== PASS_TO_PASS ==="
        if python -m pytest -rA -p no:cacheprovider tests/test_bulk_discount.py tests/test_cart.py tests/test_paginate.py tests/test_partial_page.py tests/test_slug.py; then
            p2p=1
        fi
    else
        echo "Cannot apply /tests/tests.patch" >&2
    fi
else
    echo "Cannot cd into /app" >&2
fi

resolved=$((f2p * p2p))
printf '{"resolved": %d, "f2p": %d, "p2p": %d}\n' "$resolved" "$f2p" "$p2p" \
    > "$REWARD_DIR/reward.json"
cat "$REWARD_DIR/reward.json"
exit 0
